/*
 * hooks/useChat.js
 *
 * جلب البيانات من Backend ومعالجة حالات التحميل والأخطاء
 */

import { useState, useCallback, useMemo, useEffect } from 'react';
import { STRINGS } from '../constants';
import { getCurrentUserId } from '../services/authService';
import {
  fetchUsers,
  fetchMessages,
  sendMessageAPI,
  getOrCreateChat,
} from '../services/chatService';

function formatTime() {
  return new Date().toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' });
}

export function useChat() {
  const [selectedUserId, setSelectedUserId] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [users, setUsers] = useState([]);
  const [chatIds, setChatIds] = useState({});
  const [messages, setMessages] = useState({});
  const [draft, setDraft] = useState('');
  const [loading, setLoading] = useState(true);
  const [messagesLoading, setMessagesLoading] = useState(false);
  const [sendingMessage, setSendingMessage] = useState(false);
  const [usersLoadError, setUsersLoadError] = useState('');

  useEffect(() => {
    const loadUsers = async () => {
      try {
        setLoading(true);
        setUsersLoadError('');
        const data = await fetchUsers();
        const currentUserId = getCurrentUserId();
        const otherUsers = currentUserId
          ? data.filter(u => u.id !== currentUserId)
          : data;
        setUsers(otherUsers);
        setSelectedUserId(otherUsers.length > 0 ? otherUsers[0].id : null);
      } catch (err) {
        console.error('خطأ في جلب المستخدمين:', err);
        setUsers([]);
        setSelectedUserId(null);
        setUsersLoadError(STRINGS.chat.loadUsersFailed);
      } finally {
        setLoading(false);
      }
    };

    loadUsers();
  }, []);

  const openConversation = useCallback(async (userId) => {
    try {
      setMessagesLoading(true);
      const chat = await getOrCreateChat(userId);
      setChatIds(prev => ({ ...prev, [userId]: chat.id }));

      const data = await fetchMessages(chat.id);
      setMessages(prev => ({
        ...prev,
        [userId]: data,
      }));
    } catch (err) {
      console.warn('لم يتمكن من فتح المحادثة:', err);
      setMessages(prev => ({
        ...prev,
        [userId]: [],
      }));
    } finally {
      setMessagesLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!selectedUserId) return;
    openConversation(selectedUserId);
  }, [selectedUserId, openConversation]);

  const filteredUsers = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return users;
    return users.filter(u => u.name.toLowerCase().includes(q));
  }, [users, searchQuery]);

  const selectedUser = useMemo(
    () => users.find(u => u.id === selectedUserId) ?? null,
    [users, selectedUserId],
  );

  const activeMessages = messages[selectedUserId] ?? [];

  const selectUser = useCallback((userId) => {
    setSelectedUserId(userId);
    setDraft('');
  }, []);

  const retryLoadMessages = useCallback(async () => {
    if (!selectedUserId) return;
    await openConversation(selectedUserId);
  }, [selectedUserId, openConversation]);

  const clearError = useCallback(() => {}, []);

  const sendMessage = useCallback(async () => {
    const text = draft.trim();
    if (!text || !selectedUserId) return;

    const chatId = chatIds[selectedUserId];
    if (!chatId) return;

    try {
      setSendingMessage(true);
      const newMsg = await sendMessageAPI(chatId, text);
      setMessages(prev => ({
        ...prev,
        [selectedUserId]: [...(prev[selectedUserId] ?? []), newMsg],
      }));
      setDraft('');
    } catch (err) {
      console.error('خطأ في إرسال الرسالة:', err);
      const localMsg = {
        id: `m${Date.now()}`,
        text,
        sender: 'me',
        time: formatTime(),
        failed: true,
      };
      setMessages(prev => ({
        ...prev,
        [selectedUserId]: [...(prev[selectedUserId] ?? []), localMsg],
      }));
      setDraft('');
    } finally {
      setSendingMessage(false);
    }
  }, [draft, selectedUserId, chatIds]);

  const retryMessage = useCallback(async (failedMsg) => {
    const chatId = chatIds[selectedUserId];
    if (!chatId) return;

    try {
      setSendingMessage(true);
      const newMsg = await sendMessageAPI(chatId, failedMsg.text);
      setMessages(prev => ({
        ...prev,
        [selectedUserId]: [
          ...(prev[selectedUserId] ?? []).filter(m => m.id !== failedMsg.id),
          newMsg,
        ],
      }));
    } catch (err) {
      console.error('خطأ في إعادة إرسال الرسالة:', err);
    } finally {
      setSendingMessage(false);
    }
  }, [selectedUserId, chatIds]);

  return {
    filteredUsers,
    selectedUser,
    selectedUserId,
    activeMessages,
    searchQuery,
    draft,
    setSearchQuery,
    setDraft,
    selectUser,
    sendMessage,
    loading,
    messagesLoading,
    sendingMessage,
    usersLoadError,
    retryLoadMessages,
    clearError,
    retryMessage,
  };
}
